def determine_rating_status(n, ratings):
    changed = False
    valid = True

    for i in range(1, n):
        prev_a, prev_b = ratings[i-1]
        curr_a, curr_b = ratings[i]

        if prev_a != curr_a:
            changed = True
        if prev_b < curr_b and prev_a > curr_a:
            valid = False

    if changed:
        return "rated"
    elif not valid:
        return "unrated"
    else:
        return "maybe"

