def check_rating_status(n, participants):
    sorted_by_initial_rating = sorted(participants, key=lambda x: x[0], reverse=True)
    sorted_by_final_rating = sorted(participants, key=lambda x: x[1], reverse=True)

    if len(sorted_by_initial_rating) != len(sorted_by_final_rating):
        return "maybe"

    changed_ratings = set()
    for initial, final in zip(sorted_by_initial_rating, sorted_by_final_rating):
        if initial != final:
            changed_ratings.add(initial)

    if not changed_ratings:
        return "unrated"

    for initial, final in zip(sorted_by_initial_rating, sorted_by_final_rating):
        if initial < final and initial not in changed_ratings:
            return "maybe"

    return "rated"

